<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/security.php';sh_require_admin();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){sh_verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
if($action==='delete'&&$id){$s=$db->prepare('DELETE FROM events WHERE id=?');$s->bind_param('i',$id);$s->execute();$s->close();sh_audit($db,'delete','event',$id);$msg='Event deleted.';}
elseif($action==='save'){$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$cat=trim($_POST['category']??'General');$date=str_replace('T',' ',$_POST['event_date']??'');$venue=trim($_POST['venue']??'');$cap=max(1,(int)($_POST['capacity']??100));$status=$_POST['status']??'published';$poster=null;
if(isset($_FILES['poster'])&&$_FILES['poster']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['poster'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024||!isset($allowed[$mime])||getimagesize($f['tmp_name'])===false)$msg='Poster must be a valid JPG, PNG, or WebP image up to 2 MB.';else{$poster=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/../uploads/events/'.$poster)){$poster=null;$msg='Unable to save uploaded poster.';}}}
if(!$msg&&(!$title||!$desc||!$date||!$venue||!in_array($status,['published','draft','closed'],true)))$msg='Complete all event fields.';
if(!$msg){if($id){if($poster){$s=$db->prepare('UPDATE events SET title=?,description=?,category=?,event_date=?,venue=?,capacity=?,status=?,poster=? WHERE id=?');$s->bind_param('sssssissi',$title,$desc,$cat,$date,$venue,$cap,$status,$poster,$id);}else{$s=$db->prepare('UPDATE events SET title=?,description=?,category=?,event_date=?,venue=?,capacity=?,status=? WHERE id=?');$s->bind_param('sssssisi',$title,$desc,$cat,$date,$venue,$cap,$status,$id);}$s->execute();$s->close();sh_audit($db,'update','event',$id);}else{$uid=(int)$_SESSION['user_id'];$s=$db->prepare('INSERT INTO events(title,description,category,event_date,venue,capacity,status,poster,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('sssssissi',$title,$desc,$cat,$date,$venue,$cap,$status,$poster,$uid);$s->execute();$new=$s->insert_id;$s->close();sh_audit($db,'create','event',$new);}$msg='Event saved.';}
}}
$rows=$db->query('SELECT * FROM events ORDER BY event_date DESC')->fetch_all(MYSQLI_ASSOC);$pageTitle='Events Admin | StudentHub';$assetPrefix='../';require __DIR__.'/../includes/app-header.php';?>
<h1>Event Management</h1><?php if($msg):?><p class="p15-alert"><?=sh_e($msg)?></p><?php endif;?><section class="p15-card"><h2>Create event</h2><form class="p15-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=sh_e(sh_csrf())?>"><input type="hidden" name="action" value="save"><label>Title<input name="title" required maxlength="180"></label><label>Description<textarea name="description" required></textarea></label><label>Category<input name="category" value="General"></label><label>Date and time<input type="datetime-local" name="event_date" required></label><label>Venue<input name="venue" required></label><label>Capacity<input type="number" name="capacity" min="1" value="100"></label><label>Status<select name="status"><option>published</option><option>draft</option><option>closed</option></select></label><label>Poster (JPG/PNG/WebP, max 2 MB)<input type="file" name="poster" accept="image/jpeg,image/png,image/webp"></label><button class="p15-btn">Save event</button></form></section><div class="p15-card p15-table-wrap"><table class="p15-table"><thead><tr><th>Title</th><th>Date</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $e):?><tr><td><?=sh_e($e['title'])?></td><td><?=sh_e($e['event_date'])?></td><td><?=sh_e($e['status'])?></td><td><form method="post" data-confirm="Delete event and its registrations?"><input type="hidden" name="csrf" value="<?=sh_e(sh_csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$e['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/app-footer.php';?>